            if outlen == 0 {
                return (*session).master_key_length as usize;
            }
            if outlen > (*session).master_key_length as usize {
                outlen = (*session).master_key_length as usize;
            }
            ptr::copy_nonoverlapping((*session).master_key.as_ptr(), out, outlen);
